name: release
on:
  workflow_call:
    inputs:
      unsigned-run-id:
        required: true
        type: number
    secrets:
      APPLE_SIGNING_ID: { required: true }
      APPLE_CERT_BASE64: { required: true }
      APPLE_CERT_PASSWORD: { required: true }
      APPLE_ID: { required: true }
      APPLE_PASSWORD: { required: true }
      APPLE_TEAM_ID: { required: true }
      WINDOWS_CERT_BASE64: { required: true }
      WINDOWS_CERT_PASSWORD: { required: true }
permissions:
  contents: read
  actions: read
jobs:
  sign:
    strategy:
      fail-fast: false
      matrix:
        include:
          - os: macos-latest
            target: macos
            app: unsigned/configtool.app
          - os: windows-latest
            target: windows
            app: unsigned/configtool.exe
    runs-on: ${{ matrix.os }}
    env:
      TARGET: ${{ matrix.target }}
      APP: ${{ matrix.app }}
      APPLE_SIGNING_ID: ${{ secrets.APPLE_SIGNING_ID }}
      APPLE_CERT_BASE64: ${{ secrets.APPLE_CERT_BASE64 }}
      APPLE_CERT_PASSWORD: ${{ secrets.APPLE_CERT_PASSWORD }}
      APPLE_ID: ${{ secrets.APPLE_ID }}
      APPLE_PASSWORD: ${{ secrets.APPLE_PASSWORD }}
      APPLE_TEAM_ID: ${{ secrets.APPLE_TEAM_ID }}
      WINDOWS_CERT_BASE64: ${{ secrets.WINDOWS_CERT_BASE64 }}
      WINDOWS_CERT_PASSWORD: ${{ secrets.WINDOWS_CERT_PASSWORD }}
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with:
          python-version: '3.11'
      - uses: actions/download-artifact@v4
        with:
          name: unsigned-${{ matrix.target }}
          path: unsigned
          run-id: ${{ inputs.unsigned-run-id }}
          github-token: ${{ github.token }}
      - run: bash ./release.sh
      - uses: actions/upload-artifact@v4
        with:
          name: signed-${{ matrix.target }}
          path: unsigned

#!/bin/sh
set -eu
python release/surface.py
case "$TARGET" in
  macos) sh release/signing/macos.sh ;;
  windows) pwsh -File release/signing/windows.ps1 ;;
  *) echo "unsupported target" >&2; exit 2 ;;
esac

$ErrorActionPreference = "Stop"
if (!(Test-Path $env:APP)) { throw "Missing unsigned executable" }
$certPath = Join-Path $env:RUNNER_TEMP "signing.pfx"
try {
  [IO.File]::WriteAllBytes($certPath, [Convert]::FromBase64String($env:WINDOWS_CERT_BASE64))
  $signtool = Get-ChildItem "${env:ProgramFiles(x86)}/Windows Kits/10/bin/*/x64/signtool.exe" | Sort-Object FullName -Descending | Select-Object -First 1
  if (!$signtool) { throw "Windows SDK signtool unavailable" }
  & $signtool.FullName sign /fd SHA256 /tr https://timestamp.digicert.com /td SHA256 /f $certPath /p $env:WINDOWS_CERT_PASSWORD $env:APP
  if ($LASTEXITCODE -ne 0) { throw "Signing failed" }
  & $signtool.FullName verify /pa $env:APP
  if ($LASTEXITCODE -ne 0) { throw "Signature verification failed" }
} finally { Remove-Item $certPath -ErrorAction SilentlyContinue }

import os
from pathlib import Path

SURFACE = {
    "shippedTargets": [
        "macos",
        "windows"
    ],
    "platforms": {
        "macos": {
            "signing": "release/signing/macos.sh",
            "updater": "release/updater/macos.json",
            "bundle": "release/bundles/macos.toml",
            "attribution": "release/THIRD_PARTY_NOTICES.md"
        },
        "windows": {
            "signing": "release/signing/windows.ps1",
            "updater": "release/updater/windows.json",
            "bundle": "release/bundles/windows.toml",
            "attribution": "release/THIRD_PARTY_NOTICES.md"
        }
    }
}

def validate(target):
    for role, path in SURFACE["platforms"][target].items():
        if path is None or not Path(path).is_file():
            raise RuntimeError(f"{target}: missing {role} release surface")

if __name__ == "__main__":
    validate(os.environ["TARGET"])

